states = ['q0','q1','q2','q3']
delta = {
    ('q0','a'):'q1', ('q0','b'):'q3',
    ('q1','a'):'q2', ('q1','b'):'q1',
    ('q2','a'):'q0', ('q2','b'):'q2',
    ('q3','a'):'q1', ('q3','b'):'q3'
}
final = {'q0','q3'}
alphabet = ['a','b']
index = {s:i for i,s in enumerate(states)}
def pair(p,q):
    return (p,q) if index[p] < index[q] else (q,p)
pairs = [(states[i], states[j]) for i in range(len(states)) for j in range(i+1, len(states))]
marked = set()
for p,q in pairs:
    if (p in final) != (q in final):
        marked.add(pair(p,q))
while True:
    changed = False
    for p,q in pairs:
        if pair(p,q) in marked:
            continue
        for a in alphabet:
            r = delta[(p,a)]
            s = delta[(q,a)]
            if r != s and pair(r,s) in marked:
                marked.add(pair(p,q))
                changed = True
                break
    if not changed:
        break
parent = {s:s for s in states}
def find(x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x
def union(x,y):
    rx, ry = find(x), find(y)
    if rx != ry:
        parent[ry] = rx
for p,q in pairs:
    if pair(p,q) not in marked:
        union(p,q)
classes = {}
for s in states:
    r = find(s)
    classes.setdefault(r, []).append(s)
print(len(states))
print(len(classes))
